CREATE TABLE "JobWatch" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"description" TEXT,"schedule" TEXT,"intervalMinutes" INTEGER NOT NULL DEFAULT 3,"timezone" TEXT NOT NULL DEFAULT 'America/Toronto',"sources" JSONB NOT NULL,"sourceTiers" JSONB NOT NULL,"companySlugs" JSONB NOT NULL,"companies" JSONB NOT NULL,"searchTerms" JSONB NOT NULL,"requiredTerms" JSONB NOT NULL,"preferredTerms" JSONB NOT NULL,"excludedTerms" JSONB NOT NULL,"locations" JSONB NOT NULL,"countryCodes" JSONB NOT NULL,"allowedWorkplaceTypes" JSONB NOT NULL,"allowedEmploymentTypes" JSONB NOT NULL,"minimumScore" INTEGER NOT NULL DEFAULT 60,"urgentScore" INTEGER NOT NULL DEFAULT 80,"digestScore" INTEGER NOT NULL DEFAULT 40,"notificationChannels" JSONB NOT NULL,"initializationMode" TEXT NOT NULL DEFAULT 'baseline',"initializedAt" TIMESTAMP(3),"lastRunAt" TIMESTAMP(3),"nextRunAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ObservedJob" ("id" TEXT PRIMARY KEY,"fingerprint" TEXT NOT NULL UNIQUE,"source" TEXT NOT NULL,"sourceType" TEXT,"externalJobId" TEXT,"company" TEXT,"normalizedCompany" TEXT,"title" TEXT NOT NULL,"normalizedTitle" TEXT NOT NULL,"location" TEXT,"normalizedLocation" TEXT,"workplaceType" TEXT,"employmentType" TEXT,"description" TEXT,"descriptionHash" TEXT,"jobUrl" TEXT,"applicationUrl" TEXT,"sourcePublishedAt" TIMESTAMP(3),"firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"closedAt" TIMESTAMP(3),"rawPayload" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "WatchMatch" ("id" TEXT PRIMARY KEY,"watchId" TEXT NOT NULL REFERENCES "JobWatch"("id") ON DELETE CASCADE,"observedJobId" TEXT NOT NULL REFERENCES "ObservedJob"("id") ON DELETE CASCADE,"score" INTEGER NOT NULL,"scoreBreakdown" JSONB NOT NULL,"matchedTerms" JSONB NOT NULL,"excludedReason" TEXT,"status" TEXT NOT NULL DEFAULT 'new',"firstMatchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastMatchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"notificationState" TEXT NOT NULL DEFAULT 'pending',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("watchId","observedJobId"));
CREATE TABLE "NotificationDelivery" ("id" TEXT PRIMARY KEY,"idempotencyKey" TEXT NOT NULL UNIQUE,"watchMatchId" TEXT NOT NULL REFERENCES "WatchMatch"("id") ON DELETE CASCADE,"channel" TEXT NOT NULL,"provider" TEXT NOT NULL,"status" TEXT NOT NULL,"attemptCount" INTEGER NOT NULL DEFAULT 1,"lastAttemptAt" TIMESTAMP(3),"sentAt" TIMESTAMP(3),"failedAt" TIMESTAMP(3),"providerResponse" JSONB,"errorMessage" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "WatchRun" ("id" TEXT PRIMARY KEY,"watchId" TEXT NOT NULL REFERENCES "JobWatch"("id") ON DELETE CASCADE,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),"status" TEXT NOT NULL,"sourcesRequested" JSONB NOT NULL,"sourcesSucceeded" JSONB NOT NULL,"sourcesFailed" JSONB NOT NULL,"jobsFetched" INTEGER NOT NULL DEFAULT 0,"jobsNormalized" INTEGER NOT NULL DEFAULT 0,"newJobsDetected" INTEGER NOT NULL DEFAULT 0,"matchesCreated" INTEGER NOT NULL DEFAULT 0,"notificationsSent" INTEGER NOT NULL DEFAULT 0,"durationMs" INTEGER,"errorSummary" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "JobWatch_enabled_nextRunAt_idx" ON "JobWatch"("enabled","nextRunAt"); CREATE INDEX "ObservedJob_source_externalJobId_idx" ON "ObservedJob"("source","externalJobId"); CREATE INDEX "ObservedJob_normalizedCompany_idx" ON "ObservedJob"("normalizedCompany"); CREATE INDEX "ObservedJob_sourcePublishedAt_idx" ON "ObservedJob"("sourcePublishedAt"); CREATE INDEX "WatchMatch_watchId_score_idx" ON "WatchMatch"("watchId","score"); CREATE INDEX "WatchMatch_status_idx" ON "WatchMatch"("status"); CREATE INDEX "NotificationDelivery_status_channel_idx" ON "NotificationDelivery"("status","channel"); CREATE INDEX "WatchRun_watchId_startedAt_idx" ON "WatchRun"("watchId","startedAt"); CREATE INDEX "WatchRun_status_idx" ON "WatchRun"("status");
